def _isdst(self, dt):
    tt = (dt.year, dt.month, dt.day,
          dt.hour, dt.minute, dt.second,
          dt.weekday(), 0, 0)
    try:
        stamp = _time.mktime(tt)
    except (ValueError, OverflowError):
        return False  # Too far in the future, not relevant

    tt = _time.localtime(stamp)
    return tt.tm_isdst > 0

