def _oncepost(self, dt):
    for indicator in self._lineiterators[LineIterator.IndType]:
        if len(indicator._clock) > len(indicator):
            indicator.advance()

    if self._oldsync:
        # Strategy has not been reset, the line is there
        self.advance()
    else:
        # strategy has been reset to beginning. advance step by step
        self.forward()

    self.lines.datetime[0] = dt
    self._notify()

    minperstatus = self._getminperstatus()
    if minperstatus < 0:
        self.next()
    elif minperstatus == 0:
        self.nextstart()  # only called for the 1st value
    else:
        self.prenext()

    self._next_analyzers(minperstatus, once=True)
    self._next_observers(minperstatus, once=True)

    self.clear()

def _next_observers(self, minperstatus, once=False):
    for observer in self._lineiterators[LineIterator.ObsType]:
        for analyzer in observer._analyzers:
            if minperstatus < 0:
                analyzer._next()
            elif minperstatus == 0:
                analyzer._nextstart()  # only called for the 1st value
            else:
                analyzer._prenext()

        if once:
            if len(self) > len(observer):
                if self._oldsync:
                    observer.advance()
                else:
                    observer.forward()

            if minperstatus < 0:
                observer.next()
            elif minperstatus == 0:
                observer.nextstart()  # only called for the 1st value
            elif len(observer):
                observer.prenext()
        else:
            observer._next()

def _next_analyzers(self, minperstatus, once=False):
    for analyzer in self.analyzers:
        if minperstatus < 0:
            analyzer._next()
        elif minperstatus == 0:
            analyzer._nextstart()  # only called for the 1st value
        else:
            analyzer._prenext()

